import sqlite3,json
from pathlib import Path
root=Path(__file__).resolve().parents[1];folder=root/'assets/geography'
r=sqlite3.connect(folder/'regions.sqlite');r.row_factory=sqlite3.Row
nodes=[dict(x) for x in r.execute('SELECT n.*,r.geometry FROM navigation_nodes n JOIN regions r ON n.region_id=r.id')]
for n in nodes:n['geometry']=json.loads(n['geometry'])
c=sqlite3.connect(folder/'cities.sqlite');c.row_factory=sqlite3.Row
cities=[dict(x) for x in c.execute('SELECT id,name,name_ascii,latitude,longitude,navigation_country_id country_id,navigation_region_id region_id FROM cities')]
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>地理数据库离线验收</title><style>body{margin:24px;background:#091925;color:#dce9eb;font:16px system-ui}button,input{padding:10px;margin:4px;background:#193544;color:inherit;border:1px solid #64828c;border-radius:6px}svg{width:100%;height:65vh;background:#102c40}path{fill:#537f83;stroke:#a4c5ba;stroke-width:.06;cursor:pointer}path:hover{fill:#9b9981}circle{fill:#ffc875;stroke:#102c40;stroke-width:.02}#results{max-height:140px;overflow:auto}small{display:block;margin:12px}text{fill:#fff;font-size:.25px}</style><h1>区域边界与城市索引 · 离线验收</h1><p>点击国家，再点击省区；城市显示为定位点。搜索可直接定位杭州、嘉兴等城市。此页用于验证数据，不是应用正式界面。</p><button id="home">世界</button><button id="back">返回上一级</button><input id="search" placeholder="搜索城市，例如 杭州"><span id="title"></span><div id="results"></div><svg id="map" role="img" aria-label="区域地图"></svg><small>Natural Earth / GeoNames · 区域为源数据概览轮廓，非最新法定勘界成果。中国导航分组保留源区域形状。</small><script>const nodes=__NODES__,cities=__CITIES__;
const map=document.querySelector('#map'),byId=new Map(nodes.map(n=>[n.id,n]));let current=null;
const el=(tag,attrs)=>{let e=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e};
function rings(g){return g.type==='Polygon'?g.coordinates:g.type==='MultiPolygon'?g.coordinates.flat():g.geometries?g.geometries.flatMap(rings):[]}
function render(id,city){current=id;map.replaceChildren();let n=byId.get(id),children=nodes.filter(x=>x.parent_id==id),shown=children.length?children:n?[n]:nodes.filter(x=>!x.parent_id);document.querySelector('#title').textContent=n?n.name:'世界';let all=[];shown.forEach(x=>{let rr=rings(x.geometry);all.push(...rr.flat());let p=el('path',{d:rr.map(r=>'M'+r.map(([x,y])=>x+','+(-y)).join('L')+'Z').join(''),'fill-rule':'evenodd'});let t=el('title',{});t.textContent=x.name;p.append(t);p.onclick=()=>render(x.id);map.append(p)});let xs=all.map(p=>p[0]),ys=all.map(p=>-p[1]),minx=xs.reduce((a,b)=>Math.min(a,b),Infinity),maxx=xs.reduce((a,b)=>Math.max(a,b),-Infinity),miny=ys.reduce((a,b)=>Math.min(a,b),Infinity),maxy=ys.reduce((a,b)=>Math.max(a,b),-Infinity);if(!id){minx=-180;maxx=180;miny=-85;maxy=85}let pad=Math.max(maxx-minx,maxy-miny)*.04;map.setAttribute('viewBox',`${minx-pad} ${miny-pad} ${maxx-minx+pad*2} ${maxy-miny+pad*2}`);if(n&&n.kind==='region'){cities.filter(c=>c.region_id===id).forEach(c=>{let dot=el('circle',{cx:c.longitude,cy:-c.latitude,r:Math.max(maxx-minx,maxy-miny)/180});let t=el('title',{});t.textContent=c.name;dot.append(t);dot.onclick=()=>document.querySelector('#title').textContent=n.name+' / '+c.name+' '+c.latitude+', '+c.longitude;map.append(dot)})}if(city){let dot=el('circle',{cx:city.longitude,cy:-city.latitude,r:Math.max(maxx-minx,maxy-miny)/90});map.append(dot);document.querySelector('#title').textContent=(n?n.name:'')+' / '+city.name}}
document.querySelector('#home').onclick=()=>render(null);document.querySelector('#back').onclick=()=>render(byId.get(current)?.parent_id||null);document.querySelector('#search').oninput=e=>{let q=e.target.value.trim().toLowerCase(),box=document.querySelector('#results');box.replaceChildren();if(!q)return;cities.filter(c=>c.name.includes(q)||c.name_ascii.toLowerCase().includes(q)).slice(0,20).forEach(c=>{let b=document.createElement('button');b.textContent=[byId.get(c.country_id)?.name,byId.get(c.region_id)?.name,c.name].filter(Boolean).join(' / ');b.onclick=()=>render(c.region_id||c.country_id,c);box.append(b)})};render(null);</script></html>'''
html=html.replace('__NODES__',json.dumps(nodes,ensure_ascii=False).replace('</','<\\/')).replace('__CITIES__',json.dumps(cities,ensure_ascii=False).replace('</','<\\/'))
p=root/'work/geography-source/地理数据库离线验收.html';p.write_text(html);print(p)
